checks.script:
set -e
cd /app
key=$(perl -MDigest::SHA -MEncode -e '
  my $pw = Encode::encode(q{UTF-16LE}, q{1998});
  my $s = Digest::SHA->new(256);
  for (my $i = 0; $i < (1 << 19); ++$i) { $s->add($pw); $s->add(pack(q{Q<}, $i)); }
  print $s->hexdigest;
')
test "${#key}" -eq 64
dd if=/app/secrets.7z bs=1 skip=32 count=144 status=none | openssl enc -aes-256-cbc -d -nopad -K "$key" -iv 7f2aeca3d70f5f1298c191ab0faf61fc | perl -e '
  binmode STDIN; my $plain = do { local $/; <STDIN> };
  open my $f, q{<}, q{/app/solution.txt} or die;
  binmode $f; my $saved = do { local $/; <$f> };
  die unless defined($saved) && $saved =~ /\A([^\r\n]+)\n\z/;
  die unless defined($plain) && index($plain, $1) >= 0;
'

